s=s.replace("import type {ToolCall} from '../types/ai.js';","import type {ToolCall, UsageMetadata} from '../types/ai.js';")
s+='''
// specs/hal-engine-config-hooks/spec.md: afterModelResponse receives the summed provider-call usage for the turn.
describe('addUsage', () => {
  const ROUND: UsageMetadata = {inputTokens: 2, outputTokens: 1, totalTokens: 3};

  it('sums each token field across rounds and skips rounds that reported no usage', () => {
    const rounds = [ROUND, undefined, {inputTokens: 7, outputTokens: 4, totalTokens: 11}];

    expect(rounds.reduce(addUsage, undefined)).toEqual({inputTokens: 9, outputTokens: 5, totalTokens: 14});
    expect([undefined, undefined].reduce(addUsage, undefined)).toBeUndefined();
  });
});
'''
