python3 - <<'EOF'
p='src/orchestration/orchestratorHelpers.ts'
s=open(p).read()
s=s.replace('''export function extractUsage(chunk: MessageChunk): UsageMetadata | undefined {
  return chunk.type === 'stop' ? chunk.usage : undefined;
}''','''export function extractUsage(chunk: MessageChunk): UsageMetadata | undefined {
  return chunk.type === 'stop' ? chunk.usage : undefined;
}

/** Adds one provider call's usage to a running turn total; a round that reported none leaves the total as it was. */
export function addUsage(total: UsageMetadata | undefined, round: UsageMetadata | undefined): UsageMetadata | undefined {
  if (!round) return total;
  if (!total) return round;
  return {
    inputTokens: total.inputTokens + round.inputTokens,
    outputTokens: total.outputTokens + round.outputTokens,
    totalTokens: total.totalTokens + round.totalTokens,
  };
}''')
open(p,'w').write(s)
p='src/orchestration/chatOrchestrator.ts'
s=open(p).read()
s=s.replace("  extractUsage,\n} from './orchestratorHelpers.js';","  extractUsage,\n  addUsage,\n} from './orchestratorHelpers.js';")
s=s.replace("let lastUsage: UsageMetadata | undefined;","let turnUsage: UsageMetadata | undefined;")
s=s.replace("lastUsage = outcome.usage ?? lastUsage;","turnUsage = addUsage(turnUsage, outcome.usage);")
s=s.replace("hooks.afterModelResponse(session, responseText, lastUsage)","hooks.afterModelResponse(session, responseText, turnUsage)")
open(p,'w').write(s)
EOF
